@font-face{font-family:'Anton';font-style:normal;font-weight:400;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Barlow';font-style:normal;font-weight:400;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Barlow';font-style:normal;font-weight:500;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Barlow';font-style:normal;font-weight:600;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Barlow';font-style:normal;font-weight:700;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'BarlowCondensed';font-style:normal;font-weight:500;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'BarlowCondensed';font-style:normal;font-weight:600;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'BarlowCondensed';font-style:normal;font-weight:700;src:url(data:font/ttf;base64,) format('truetype');}

*{margin:0;padding:0;box-sizing:border-box}
:root{--ink:#17120F;--red:#8B0000;--crimson:#B4141B;--gold:#A9793A;--goldD:#875318;--ivory:#F7F2EA;--line:rgba(139,0,0,.16);--soft:rgba(23,18,15,.62)}
@page{size:210mm 297mm;margin:0}
html,body{font-family:'Barlow',sans-serif;color:var(--ink)}
.page{position:relative;width:210mm;height:297mm;overflow:hidden;page-break-after:always;background:var(--ivory)}
.page:last-child{page-break-after:auto}
.bg{background-image:url('../assets/bg.jpg');background-size:210mm 297mm;background-repeat:no-repeat}
.pad{position:absolute;top:25mm;left:15.5mm;right:15.5mm;bottom:21mm}
.rhead{position:absolute;top:9.2mm;right:15.5mm;font-family:'BarlowCondensed';font-weight:600;font-size:8pt;letter-spacing:.18em;color:var(--soft);text-transform:uppercase}
.foot{position:absolute;left:15.5mm;right:15.5mm;bottom:6.4mm;display:flex;justify-content:space-between;font-family:'BarlowCondensed';font-weight:600;font-size:7.6pt;letter-spacing:.16em;color:var(--soft);text-transform:uppercase}
.foot .pg{color:var(--red)}
.kicker{font-family:'BarlowCondensed';font-weight:700;font-size:10.5pt;letter-spacing:.34em;color:var(--gold);text-transform:uppercase}
.kicker.red{color:var(--crimson)}
.h1{font-family:'Anton';font-size:40pt;line-height:.92;letter-spacing:.005em;color:var(--ink);text-transform:uppercase;margin-top:1.2mm}
.h1 .rd{color:var(--red)}
.h1.sm{font-size:28pt}
.lead{font-size:10.8pt;line-height:1.42;color:#241d18;margin-top:2.4mm}
.lead b{color:var(--red);font-weight:600}
.body{font-size:9.7pt;line-height:1.4;color:#2b241e}
.body b{color:var(--red);font-weight:600}
.rule{display:flex;align-items:center;margin:2.8mm 0}
.rule .r1{height:.75mm;width:22mm;background:var(--red);flex:0 0 auto}
.rule .r2{height:.3mm;flex:1 1 auto;background:rgba(169,121,58,.55)}
.chip{display:inline-block;font-family:'Barlow';font-weight:600;font-size:8.3pt;color:#3a2f27;background:rgba(169,121,58,.12);border:0.2mm solid rgba(169,121,58,.4);border-radius:20mm;padding:.7mm 2.6mm;margin:.8mm 1.2mm 0 0;white-space:nowrap}
.chip.big{font-size:9pt;padding:1mm 3mm}
.ph{border:0.4mm dashed rgba(139,0,0,.45);background:rgba(139,0,0,.035);border-radius:2mm;padding:0 2mm;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--red)}
.ph .ic{font-family:'Anton';font-size:15pt;opacity:.5}
.ph .lb{font-family:'BarlowCondensed';font-weight:700;font-size:7.4pt;letter-spacing:.14em;text-transform:uppercase;margin-top:1mm;color:rgba(139,0,0,.72)}
.ph .nm{font-family:'Barlow';font-weight:700;font-size:8.6pt;color:var(--ink);margin-top:.6mm}
.sesshead{position:relative;margin-top:.4mm}
.snum{font-family:'Anton';font-size:12pt;color:#fff;background:var(--red);border-radius:1.5mm;padding:.4mm 2.2mm;letter-spacing:.02em}
.stitle{font-family:'BarlowCondensed';font-weight:700;font-size:13.5pt;letter-spacing:.02em;text-transform:uppercase;color:var(--ink);vertical-align:middle}
.stime{font-family:'BarlowCondensed';font-weight:600;font-size:10pt;letter-spacing:.1em;color:var(--gold);text-transform:uppercase}
.rail{position:relative;margin-top:1.3mm;padding-left:2mm}
.railline{position:absolute;left:26.4mm;top:1.3mm;bottom:1.3mm;width:.5mm;background:linear-gradient(var(--gold),rgba(169,121,58,.25))}
.trow{display:flex;align-items:flex-start;break-inside:avoid;padding:1.05mm 0}
.trow+.trow{border-top:.18mm solid var(--line)}
.tt{width:24mm;flex:0 0 24mm;text-align:right;font-family:'BarlowCondensed';font-weight:600;font-size:9pt;color:var(--crimson);padding-top:.3mm;letter-spacing:.02em}
.tdot{flex:0 0 5mm;display:flex;justify-content:center;padding-top:1mm}
.tdot i{width:2.1mm;height:2.1mm;border-radius:50%;background:var(--gold);display:block;box-shadow:0 0 0 .7mm var(--ivory)}
.tb{flex:1 1 auto;padding-left:1.5mm}
.tb .top{font-family:'Barlow';font-weight:600;font-size:9.3pt;line-height:1.18;color:#241d18}
.tb .fac{font-family:'Barlow';font-weight:600;font-size:7.9pt;color:var(--gold);margin-top:.2mm}
.trow.feat .tb .top{color:var(--red);font-weight:700}
.trow.brk .tt{color:var(--soft)}
.trow.brk .tb .top{font-family:'BarlowCondensed';font-weight:700;letter-spacing:.14em;text-transform:uppercase;font-size:9pt;color:var(--soft)}
.trow.brk .tdot i{background:var(--soft)}
.panel{margin-top:1.4mm;background:rgba(139,0,0,.05);border-left:1mm solid var(--red);border-radius:1mm;padding:2.4mm 3mm}
.panel .pt{font-family:'BarlowCondensed';font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--red);font-size:9.4pt}
.panel .pb{font-size:9.2pt;line-height:1.4;color:#2b241e;margin-top:1mm}
.daytag{display:inline-block;font-family:'Anton';font-size:11pt;color:#fff;padding:.6mm 3mm;border-radius:1.4mm;letter-spacing:.04em}
.d0{background:var(--gold)} .d1{background:var(--crimson)} .d2{background:var(--red)}
.cardgrid{display:flex;flex-wrap:wrap;gap:2.4mm;margin-top:2.2mm}
.card{flex:1 1 46%;min-width:46%;background:rgba(255,255,255,.5);border:.2mm solid var(--line);border-radius:2mm;padding:2.5mm 3mm;break-inside:avoid}
.card .cn{font-family:'Anton';font-size:13pt;color:rgba(139,0,0,.25);float:right;line-height:1}
.card .ct{font-family:'BarlowCondensed';font-weight:700;font-size:12pt;letter-spacing:.02em;text-transform:uppercase;color:var(--ink)}
.card .cd{font-size:9pt;line-height:1.4;color:#33291f;margin-top:1.4mm}
.mantra{font-family:'Anton';font-size:19pt;text-transform:uppercase;color:var(--ink);letter-spacing:.01em;line-height:1.05}
.mantra .s{color:var(--red)}
.lab{break-inside:avoid;background:rgba(255,255,255,.5);border:.2mm solid var(--line);border-left:1mm solid var(--gold);border-radius:1.5mm;padding:2.2mm 2.8mm;margin-bottom:0}
.lab .lt{font-family:'BarlowCondensed';font-weight:700;font-size:12pt;letter-spacing:.03em;text-transform:uppercase;color:var(--red)}
.lab .li{font-size:8.8pt;color:#33291f;line-height:1.45;margin-top:.8mm}
.two{display:flex;gap:6mm}
.two>div{flex:1}
